P1_Card_OTIF_HTML:
VAR _Total = COUNTROWS(Fact_Shipments_OTIF)
VAR _Compliant = CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1)
VAR _Rate = DIVIDE(_Compliant, _Total, 0)
VAR _RateFmt = FORMAT(_Rate, "0.0%")
VAR _CompFmt = FORMAT(_Compliant, "#,##0")
VAR _TotalFmt = FORMAT(_Total, "#,##0")
RETURN
"<link rel='preconnect' href='https://fonts.googleapis.com'>
<link href='https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@700;800&family=Playfair+Display:wght@700;800&display=swap' rel='stylesheet'>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
