P1_Visual_OTIF_Trend_HTML:
VAR _TotalOrders = COUNTROWS(Fact_Shipments_OTIF)
VAR _CompliantOrders = CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1)
VAR _OTIFRate = DIVIDE(_CompliantOrders, _TotalOrders, 0)
VAR _OTIFPct = FORMAT(_OTIFRate, "0.0%")

VAR _SepRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "September")
VAR _OctRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "October")
VAR _NovRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "November")
VAR _DecRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "December")
VAR _JanRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "January")
VAR _FebRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "February")
VAR _MarRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "March")
VAR _AprRate = CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0), Dim_Date[MonthName] = "April")

VAR _Scale = 8000.0
VAR _Y0 = 45.0 + (1.0 - _SepRate) * _Scale
VAR _Y1 = 45.0 + (1.0 - _OctRate) * _Scale
VAR _Y2 = 45.0 + (1.0 - _NovRate) * _Scale
VAR _Y3 = 45.0 + (1.0 - _DecRate) * _Scale
VAR _Y4 = 45.0 + (1.0 - _JanRate) * _Scale
VAR _Y5 = 45.0 + (1.0 - _FebRate) * _Scale
VAR _Y6 = 45.0 + (1.0 - _MarRate) * _Scale
VAR _Y7 = 45.0 + (1.0 - _AprRate) * _Scale

VAR _C1_0 = _Y0 + (_Y1 - _Y0) / 6.0
VAR _C2_0 = _Y1 - (_Y2 - _Y0) / 6.0
VAR _C1_1 = _Y1 + (_Y2 - _Y0) / 6.0
VAR _C2_1 = _Y2 - (_Y3 - _Y1) / 6.0
VAR _C1_2 = _Y2 + (_Y3 - _Y1) / 6.0
VAR _C2_2 = _Y3 - (_Y4 - _Y2) / 6.0
VAR _C1_3 = _Y3 + (_Y4 - _Y2) / 6.0
VAR _C2_3 = _Y4 - (_Y5 - _Y3) / 6.0
VAR _C1_4 = _Y4 + (_Y5 - _Y3) / 6.0
VAR _C2_4 = _Y5 - (_Y6 - _Y4) / 6.0
VAR _C1_5 = _Y5 + (_Y6 - _Y4) / 6.0
VAR _C2_5 = _Y6 - (_Y7 - _Y5) / 6.0
VAR _C1_6 = _Y6 + (_Y7 - _Y5) / 6.0
VAR _C2_6 = _Y7 - (_Y7 - _Y6) / 6.0

VAR _PathD = "M 40.0," & FORMAT(_Y0, "0.0") & 
    " C 50.0," & FORMAT(_C1_0, "0.0") & " 80.0," & FORMAT(_C2_0, "0.0") & " 100.0," & FORMAT(_Y1, "0.0") & 
    " C 120.0," & FORMAT(_C1_1, "0.0") & " 140.0," & FORMAT(_C2_1, "0.0") & " 160.0," & FORMAT(_Y2, "0.0") & 
    " C 180.0," & FORMAT(_C1_2, "0.0") & " 200.0," & FORMAT(_C2_2, "0.0") & " 220.0," & FORMAT(_Y3, "0.0") & 
    " C 240.0," & FORMAT(_C1_3, "0.0") & " 260.0," & FORMAT(_C2_3, "0.0") & " 280.0," & FORMAT(_Y4, "0.0") & 
    " C 300.0," & FORMAT(_C1_4, "0.0") & " 320.0," & FORMAT(_C2_4, "0.0") & " 340.0," & FORMAT(_Y5, "0.0") & 
    " C 360.0," & FORMAT(_C1_5, "0.0") & " 380.0," & FORMAT(_C2_5, "0.0") & " 400.0," & FORMAT(_Y6, "0.0") & 
    " C 420.0," & FORMAT(_C1_6, "0.0") & " 450.0," & FORMAT(_C2_6, "0.0") & " 460.0," & FORMAT(_Y7, "0.0")

VAR _AreaD = _PathD & " L 460.0,260 L 40.0,260 Z"

RETURN
"<link rel='preconnect' href='https://fonts.googleapis.com'>
<link href='https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap' rel='stylesheet'>
<style>
