    <svg class='chart-svg' viewBox='0 0 500 300'>
      <defs>
        <linearGradient id='gold_area' x1='0%' y1='0%' x2='0%' y2='100%'>
          <stop offset='0%' stop-color='#C7A462' stop-opacity='0.25'/>
          <stop offset='100%' stop-color='#C7A462' stop-opacity='0.01'/>
        </linearGradient>
        <filter id='dot_glow' x='-50%' y='-50%' width='200%' height='200%'>
          <feDropShadow dx='0' dy='2' stdDeviation='2.5' flood-color='#7A5C30' flood-opacity='0.35'/>
        </filter>
      </defs>

      <!-- 4 Horizontal Guide Lines (100%, 99%, 98%, 97%) -->
      <line x1='38' y1='45' x2='462' y2='45' stroke='#E6DFD5' stroke-width='1' stroke-dasharray='3 3'/>
      <text x='32' y='49' font-family='Plus Jakarta Sans' font-size='10' font-weight='600' fill='#9CA8B8' text-anchor='end'>100%</text>

      <line x1='38' y1='125' x2='462' y2='125' stroke='#E6DFD5' stroke-width='1' stroke-dasharray='3 3'/>
      <text x='32' y='129' font-family='Plus Jakarta Sans' font-size='10' font-weight='600' fill='#9CA8B8' text-anchor='end'>99%</text>

      <!-- 98.5% Target Line -->
      <line x1='38' y1='165' x2='462' y2='165' stroke='#2E6930' stroke-width='1.3' stroke-dasharray='4 4' stroke-opacity='0.85'/>
      <text x='466' y='168' font-family='Plus Jakarta Sans' font-size='9.5' font-weight='700' fill='#2E6930'>Target 98.5%</text>

      <line x1='38' y1='205' x2='462' y2='205' stroke='#E6DFD5' stroke-width='1' stroke-dasharray='3 3'/>
      <text x='32' y='209' font-family='Plus Jakarta Sans' font-size='10' font-weight='600' fill='#9CA8B8' text-anchor='end'>98%</text>

      <!-- Dynamic Spline Area & Line -->
      <path d='" & _AreaD & "' fill='url(#gold_area)'/>
      <path d='" & _PathD & "' fill='none' stroke='#C7A462' stroke-width='3.5' stroke-linecap='round' filter='url(#dot_glow)'/>

      <!-- Sep: 99.0% (Above Target) -->
      <text class='chart-val' x='40.0' y='" & FORMAT(_Y0 - 13, "0.0") & "'>" & FORMAT(_SepRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='40.0' cy='" & FORMAT(_Y0, "0.0") & "' r='5' fill='#FFFFFF' stroke='#C7A462' stroke-width='2.5'><title>September: " & FORMAT(_SepRate, "0.00%") & "</title></circle>

      <!-- Oct: 98.7% (Above Target) -->
      <text class='chart-val' x='100.0' y='" & FORMAT(_Y1 - 13, "0.0") & "'>" & FORMAT(_OctRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='100.0' cy='" & FORMAT(_Y1, "0.0") & "' r='5' fill='#FFFFFF' stroke='#C7A462' stroke-width='2.5'><title>October: " & FORMAT(_OctRate, "0.00%") & "</title></circle>

      <!-- Nov: 98.1% (Below Target Dip -> Label Below) -->
      <text class='chart-val val-amber' x='160.0' y='" & FORMAT(_Y2 + 19, "0.0") & "'>" & FORMAT(_NovRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='160.0' cy='" & FORMAT(_Y2, "0.0") & "' r='6.5' fill='#C7A462' stroke='#8C5305' stroke-width='2.5' filter='url(#dot_glow)'><title>November (Christmas Peak): " & FORMAT(_NovRate, "0.00%") & "</title></circle>

      <!-- Dec: 99.0% (Rebound Above Target) -->
      <text class='chart-val' x='220.0' y='" & FORMAT(_Y3 - 13, "0.0") & "'>" & FORMAT(_DecRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='220.0' cy='" & FORMAT(_Y3, "0.0") & "' r='5' fill='#FFFFFF' stroke='#C7A462' stroke-width='2.5'><title>December: " & FORMAT(_DecRate, "0.00%") & "</title></circle>

      <!-- Jan: 99.5% (Peak Above Target) -->
      <text class='chart-val' x='280.0' y='" & FORMAT(_Y4 - 13, "0.0") & "'>" & FORMAT(_JanRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='280.0' cy='" & FORMAT(_Y4, "0.0") & "' r='5.5' fill='#FFFFFF' stroke='#C7A462' stroke-width='2.5'><title>January: " & FORMAT(_JanRate, "0.00%") & "</title></circle>

      <!-- Feb: 98.4% (Below Target Dip -> Label Below) -->
      <text class='chart-val val-amber' x='340.0' y='" & FORMAT(_Y5 + 19, "0.0") & "'>" & FORMAT(_FebRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='340.0' cy='" & FORMAT(_Y5, "0.0") & "' r='5' fill='#FFFFFF' stroke='#8C5305' stroke-width='2.5'><title>February: " & FORMAT(_FebRate, "0.00%") & "</title></circle>

      <!-- Mar: 99.3% (Easter Peak Above Target) -->
      <text class='chart-val' x='400.0' y='" & FORMAT(_Y6 - 13, "0.0") & "'>" & FORMAT(_MarRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='400.0' cy='" & FORMAT(_Y6, "0.0") & "' r='6.5' fill='#C7A462' stroke='#11632D' stroke-width='2.5' filter='url(#dot_glow)'><title>March (Easter Peak): " & FORMAT(_MarRate, "0.00%") & "</title></circle>

      <!-- Apr: 98.3% (Below Target Dip -> Label Below) -->
      <text class='chart-val val-amber' x='460.0' y='" & FORMAT(_Y7 + 19, "0.0") & "'>" & FORMAT(_AprRate, "0.0%") & "</text>
      <circle class='chart-dot' cx='460.0' cy='" & FORMAT(_Y7, "0.0") & "' r='5' fill='#FFFFFF' stroke='#8C5305' stroke-width='2.5'><title>April: " & FORMAT(_AprRate, "0.00%") & "</title></circle>

      <!-- Month Labels -->
      <text class='axis-lbl' x='40.0' y='285'>Sep</text>
      <text class='axis-lbl' x='100.0' y='285'>Oct</text>
      <text class='axis-lbl' x='160.0' y='285' fill='#0E1726' font-weight='800'>Nov</text>
      <text class='axis-lbl' x='220.0' y='285'>Dec</text>
      <text class='axis-lbl' x='280.0' y='285'>Jan</text>
      <text class='axis-lbl' x='340.0' y='285'>Feb</text>
      <text class='axis-lbl' x='400.0' y='285' fill='#0E1726' font-weight='800'>Mar</text>
      <text class='axis-lbl' x='460.0' y='285'>Apr</text>
    </svg>
  </div>
</div>"

P1_Visual_Retailers_League_HTML:
VAR _Retailers = 
    ADDCOLUMNS(
        SUMMARIZE(Dim_CustomerChannel, Dim_CustomerChannel[CustomerName]),
        "@Orders", CALCULATE(COUNTROWS(Fact_Shipments_OTIF)),
        "@Rev", CALCULATE(SUM(Fact_Shipments_OTIF[Revenue_GBP])),
        "@Compliant", CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1),
        "@OTIF", CALCULATE(DIVIDE(CALCULATE(COUNTROWS(Fact_Shipments_OTIF), Fact_Shipments_OTIF[OTIFFlag] = 1), COUNTROWS(Fact_Shipments_OTIF), 0))
    )
VAR _RowsHTML = 
    CONCATENATEX(
        _Retailers,
        VAR _CustName = [CustomerName]
        VAR _DisplayName = IF(_CustName = "Lindt Boutiques & Outlet Stores", "Lindt Boutiques", _CustName)
        VAR _IsOnTarget = [@OTIF] >= 0.985
        VAR _BadgeClass = IF(_IsOnTarget, "badge-green", "badge-amber")
        VAR _TitleAttr = _CustName & ": " & FORMAT([@Orders], "#,##0") & " Orders | £" & FORMAT([@Rev]/1000000, "0.0") & "M Revenue | " & FORMAT([@OTIF], "0.0%") & " Delivery Rate"
        RETURN
        "<div class='customer-row' title='" & _TitleAttr & "'>" &
            "<span class='customer-name'>" & _DisplayName & "</span>" &
            "<div class='customer-right'>" &
                "<span class='customer-rev'>&pound;" & FORMAT([@Rev]/1000000, "0.0") & "M</span>" &
                "<span class='badge-otif " & _BadgeClass & "'>" & FORMAT([@OTIF], "0.0%") & "</span>" &
            "</div>" &
        "</div>",
        "",
        [@Rev],
        DESC
    )
RETURN
"<link rel='preconnect' href='https://fonts.googleapis.com'>
