P2_Visual_Plants_Breakdown_HTML:
VAR _Plants = 
    ADDCOLUMNS(
        SUMMARIZE(Fact_Production_Batches, Fact_Production_Batches[ProductionPlant]),
        "@Batches", CALCULATE(COUNTROWS(Fact_Production_Batches)),
        "@ActualMT", CALCULATE(SUM(Fact_Production_Batches[ActualVolume_MT])),
        "@PlannedMT", CALCULATE(SUM(Fact_Production_Batches[PlannedVolume_MT])),
        "@Conching", CALCULATE(AVERAGE(Fact_Production_Batches[ConchingHours])),
        "@Quality", CALCULATE(AVERAGE(Fact_Production_Batches[QualityScorePct]))
    )
VAR _MaxMT = 10607
VAR _RowsHTML = 
    CONCATENATEX(
        _Plants,
        VAR _PName = [ProductionPlant]
        VAR _Country = IF(CONTAINSSTRING(_PName, "Switzerland"), "CH", IF(CONTAINSSTRING(_PName, "Germany"), "DE", "AT"))
        VAR _CleanName = SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(_PName, " Plant (Switzerland)", ""), " Plant (Germany)", ""), " Plant (Austria)", "")
        VAR _FullClean = _CleanName & " (" & _Country & ")"
        VAR _ActualMT = [@ActualMT]
        VAR _PlannedMT = [@PlannedMT]
        VAR _Yield = DIVIDE(_ActualMT, _PlannedMT, 0)
        VAR _YieldFmt = FORMAT(_Yield, "0.0%")
        VAR _BarWidth = FORMAT(DIVIDE(_ActualMT, _MaxMT, 0) * 100, "0") & "%"
        VAR _TitleAttr = _PName & ": " & FORMAT(_ActualMT, "#,##0") & " MT | " & FORMAT([@Batches], "#,##0") & " Batches | Conching: " & FORMAT([@Conching], "0.0") & "h | Quality: " & FORMAT([@Quality], "0.0") & "%"
        RETURN
        "<div class='plant-card' title='" & _TitleAttr & "'>" &
            "<div class='plant-top'>" &
                "<div class='plant-name-wrap'>" &
                    "<span class='plant-flag'>" & _Country & "</span>" &
                    "<span class='plant-name'>" & _FullClean & "</span>" &
                "</div>" &
                "<div class='plant-stats'>" &
                    "<span class='plant-mt'>" & FORMAT(_ActualMT, "#,##0") & " MT</span>" &
                    "<span class='badge-yield'>" & _YieldFmt & "</span>" &
                "</div>" &
            "</div>" &
            "<div class='plant-meta'>" &
                "<span>Batches: <b>" & FORMAT([@Batches], "#,##0") & "</b></span>" &
                "<span>Conching: <b>" & FORMAT([@Conching], "0.0") & "h</b></span>" &
                "<span>Sensory: <b style='color:#11632D;'>" & FORMAT([@Quality], "0.0") & "%</b></span>" &
            "</div>" &
            "<div class='progress-track'>" &
                "<div class='progress-fill' style='width:" & _BarWidth & ";'></div>" &
            "</div>" &
        "</div>",
        "",
        [@ActualMT],
        DESC
    )
RETURN
