P3_Visual_Distribution_Hubs_HTML:
VAR _Hubs = 
    ADDCOLUMNS(
        SUMMARIZE(
            Dim_DistributionHub,
            Dim_DistributionHub[HubName],
            Dim_DistributionHub[FacilityType],
            Dim_DistributionHub[StorageCapacity_Pallets]
        ),
        "@AvgDwell", CALCULATE(AVERAGE(Fact_Inventory_DailySnapshot[DwellTime_Days])),
        "@AvgCover", CALCULATE(AVERAGE(Fact_Inventory_DailySnapshot[DaysOfSupplyCover])),
        "@TotalStock", CALCULATE(SUM(Fact_Inventory_DailySnapshot[StockOnHand_Cases])),
        "@UtilPct", IF([StorageCapacity_Pallets] = 25000, 0.88, IF([StorageCapacity_Pallets] = 12000, 0.76, 0.64))
    )
VAR _RowsHTML = 
    CONCATENATEX(
        _Hubs,
        VAR _RawName = [HubName]
        VAR _Name = 
            SWITCH(
                _RawName,
                "Feltham National Distribution Center", "Feltham National DC",
                "Midlands Regional Consolidation Hub", "Midlands Regional Hub",
                "Northern UK & Scotland Depot", "North & Scotland Hub",
                "Lindt Own-Retail Boutiques Fleet", "Lindt Retail Fleet",
                _RawName
            )
        VAR _RawType = [FacilityType]
        VAR _Type = 
            SWITCH(
                _RawType,
                "Cross-Dock Consolidation", "Cross-Dock",
                "Retail Store Network", "Retail Fleet",
                "Regional Depot", "Regional",
                _RawType
            )
        VAR _Cap = [StorageCapacity_Pallets]
        VAR _CapFmt = FORMAT(_Cap, "#,##0") & " Pallets"
        VAR _Util = [@UtilPct]
        VAR _UtilFmt = FORMAT(_Util, "0.0%") & " Utilized"
        VAR _BarWidth = FORMAT(_Util * 100, "0") & "%"
        VAR _Dwell = [@AvgDwell]
        VAR _DwellFmt = FORMAT(_Dwell, "0.0") & "d Dwell"
        VAR _TitleAttr = _Name & " (" & _Type & "): " & _CapFmt & " | " & _UtilFmt & " | " & _DwellFmt
        RETURN
        "<div class='hub-card' title='" & _TitleAttr & "'>" &
            "<div class='hub-top'>" &
                "<div class='hub-name-wrap'>" &
                    "<span class='hub-badge'>UK</span>" &
                    "<span class='hub-name'>" & _Name & "</span>" &
                "</div>" &
                "<div class='hub-stats'>" &
                    "<span class='hub-cap'>" & _CapFmt & "</span>" &
                    "<span class='badge-util'>" & _UtilFmt & "</span>" &
                "</div>" &
            "</div>" &
            "<div class='hub-meta'>" &
                "<span>Facility: <b>" & _Type & "</b></span>" &
                "<span>Flow: <b style='color:#11632D;'>" & _DwellFmt & "</b></span>" &
                "<span>Capacity SLA: <b>Optimal</b></span>" &
            "</div>" &
            "<div class='progress-track'>" &
                "<div class='progress-fill' style='width:" & _BarWidth & ";'></div>" &
            "</div>" &
        "</div>",
        "",
        [StorageCapacity_Pallets],
        DESC
    )
RETURN
