    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 50% 35%, rgba(255, 255, 255, 0.94) 0%, rgba(248, 246, 240, 0.92) 55%, rgba(243, 239, 230, 0.97) 100%);
    z-index: 2;
    pointer-events: none;
  }

  .cover-vig {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at center, transparent 60%, rgba(199, 164, 98, 0.08) 100%);
    z-index: 3;
    pointer-events: none;
  }

  /* Content Layer */
  .content-wrap {
    position: relative;
    z-index: 10;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: center;
  }

  /* ═══ TOP HEADER ═══ */
  .header-bar {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    opacity: 0;
    animation: fadeIn 1s ease 0.2s forwards;
  }

  .brand-eyebrow {
