  }

  .gold-divider {
    width: 24px;
    height: 1.5px;
    background: var(--gold);
    display: inline-block;
  }

  .portal-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 20px;
    border-radius: 999px;
    background: #FFFFFF;
    border: 1.5px solid var(--gold-border);
    font-size: 11.5px;
    font-weight: 700;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--navy-deep);
    box-shadow: 0 4px 14px rgba(14, 23, 38, 0.04);
  }

  .portal-pill span {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--gold);
    display: inline-block;
  }

  /* ═══ CENTER HERO ═══ */
  .hero-section {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    max-width: 900px;
    margin-top: -10px;
  }

  .hero-title {
    font-family: var(--font-serif);
    font-size: 68px;
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.015em;
    color: var(--navy-deep);
    margin-bottom: 12px;
    opacity: 0;
    filter: blur(12px);
    transform: translateY(16px);
