  /* ═══ 3 NAVIGATION CARDS ═══ */
  .cards-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
    width: 100%;
    max-width: 1120px;
    margin-bottom: 15px;
  }

  .nav-card {
    background: var(--card-bg);
    border: 1.5px solid var(--gold-border);
    border-radius: 16px;
    padding: 34px 30px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 200px;
    position: relative;
    overflow: hidden;
    cursor: pointer;
    text-decoration: none;
    box-shadow: 0 8px 24px rgba(14, 23, 38, 0.04);
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    opacity: 0;
    transform: translateY(18px);
    animation: cardIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  .nav-card:nth-child(1) { animation-delay: 0.7s; }
  .nav-card:nth-child(2) { animation-delay: 0.85s; }
  .nav-card:nth-child(3) { animation-delay: 1.0s; }

  .nav-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3.5px;
    background: linear-gradient(90deg, var(--gold), var(--gold-light));
    opacity: 0.8;
    transition: height 0.3s ease, opacity 0.3s ease;
  }

  .nav-card:hover {
    transform: translateY(-6px);
    border-color: var(--gold);
    box-shadow: 0 20px 45px rgba(14, 23, 38, 0.10), 0 0 20px rgba(199, 164, 98, 0.18);
  }

  .nav-card:hover::before {
    height: 5px;
    opacity: 1;
  }

  .card-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .card-kicker {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--gold);
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .card-title {
    font-family: var(--font-serif);
    font-size: 32px;
    font-weight: 700;
    color: var(--navy-deep);
    line-height: 1.15;
    letter-spacing: -0.01em;
  }

  .card-sub {
    font-size: 15px;
    font-weight: 400;
    color: var(--text-muted);
    line-height: 1.4;
    letter-spacing: 0.01em;
    margin-top: 2px;
  }

  .card-bottom {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    padding-top: 18px;
    margin-top: 14px;
    border-top: 1px solid #F0EAE1;
  }

  .card-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 20px;
    border-radius: 8px;
    background: var(--navy-deep);
    color: #FFFFFF;
    font-size: 12.5px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    transition: all 0.25s ease;
  }

  .card-btn span {
    color: var(--gold);
    font-size: 15px;
    transition: transform 0.25s ease;
  }

  .nav-card:hover .card-btn {
    background: var(--navy-light);
    box-shadow: 0 4px 14px rgba(14, 23, 38, 0.2);
  }

  .nav-card:hover .card-btn span {
    transform: translateX(4px);
  }

  /* ═══ FOOTER ═══ */
  .footer-bar {
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    opacity: 0;
    animation: fadeIn 1s ease 1.1s forwards;
  }

  .footer-text {
    font-size: 11.5px;
    font-weight: 500;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: #9C9488;
  }

  /* ═══ ANIMATIONS ═══ */
  @keyframes fadeIn {
    to { opacity: 1; transform: translateY(0); }
  }

  @keyframes rvTitle {
    to { opacity: 1; filter: blur(0); transform: translateY(0); }
  }

  @keyframes cardIn {
    to { opacity: 1; transform: translateY(0); }
  }
</style>
</head>
